<?php use function KB\{e,url}; use KB\Security; ?><section class="auth-card panel"><span class="eyebrow">ACCOUNT SECURITY</span><h1>Choose a new password.</h1><?php if(!$valid): ?><div class="notice error">This link is invalid, expired or already used.</div><a class="button" href="<?= e(url('forgot-password')) ?>">Request a new link</a><?php else: ?><?php if($error): ?><div class="notice error"><?= e($error) ?></div><?php endif; ?><form class="stack" method="post" action="<?= e(url('reset-password',['token'=>$token])) ?>"><?= Security::csrfField() ?><label>New password<input type="password" name="password" minlength="12" maxlength="72" autocomplete="new-password" required></label><label>Confirm new password<input type="password" name="password_confirm" minlength="12" maxlength="72" autocomplete="new-password" required></label><small class="muted">At least 12 characters. Changing your password signs out other sessions.</small><button class="button full">Save new password</button></form><?php endif; ?></section>
